from durationkit import parse_duration
from durationkit.parse import parse_duration as direct
assert parse_duration is direct
valid = {'90': 90.0, '  42 ': 42.0, '0': 0.0, '0007': 7.0, '2d': 172800.0, '3h': 10800.0, '15m': 900.0, '45s': 45.0, '500ms': 0.5, '1h30m': 5400.0, '2d4h': 187200.0, '1m1s': 61.0, '1s500ms': 1.5, '1d1h1m1s1ms': 90061.001, '1d1ms': 86400.001, '90m': 5400.0, '1500ms': 1.5, '0s': 0.0, '0ms': 0.0, '0d0h0m0s0ms': 0.0, '01h030m': 5400.0, ' 1h 30m ': 5400.0, '\t1h\n30m\r': 5400.0, '１２': 12.0, '١h٣٠m': 5400.0}
for value, expected in valid.items():
    actual = parse_duration(value)
    assert isinstance(actual, float) and abs(actual - expected) <= 1e-9, (value, actual, expected)
invalid = ['', '   ', '\t\n', '-1', '-1h', '+1', '+1h', '1.5', '1.5h', '1e3s', '1_000s', '1x', '1H', '1MS', '1sec', '1h1h', '1ms2ms', '0s0s', '30m1h', '1ms1s', '0s0m', 'h', 'ms', '1h30', '90 1s', '1 2', 'abc', '1h,30m', '1s!', '1 h', '1m s', '²']
for value in invalid:
    try: parse_duration(value)
    except ValueError: pass
    else: raise AssertionError(('accepted invalid input', value))
for value in (90, None, 1.5, True, b'90', []):
    try: parse_duration(value)
    except TypeError: pass
    else: raise AssertionError(('accepted non-string input', value))
print(f'Validated {len(valid)} valid, {len(invalid)} malformed, and 6 non-string cases.')
